from core import *

def papers():
 p=[]
 p.append(item('What is 1000 − 275?',725,'Subtract 200 to get 800, then subtract 75 to get 725. Check by adding 725+275=1000.','DIG-01',[625,675,735,825],check=1000-275))
 p.append(item('A carton holds 18 eggs. Five eggs break. How many unbroken eggs remain?',13,'Take the five broken eggs away from the original eighteen: 18−5=13 unbroken eggs.','DIG-01',[11,12,14,23],check=18-5))
 p.append(item('The letters A, B, C stand for 1, 2, 3 respectively. What is the value of C×B+A?',7,'Substitute the values and multiply first: 3×2+1=6+1=7. Adding before multiplication would give a different expression.','ALG-01',[5,6,8,9],check=3*2+1))
 p.append(item('Which is the smallest decimal number?','0.08','Compare the numbers in hundredths: 0.08=8, 0.18=18, 0.80=80, 0.81=81, and 0.88=88 hundredths. Eight hundredths is smallest.','DIG-01',['0.18','0.80','0.81','0.88']))
 p.append(item('How many minutes are there in one hour and three quarters of an hour?',105,'One hour is 60 minutes. Three quarters of 60 is 45. Together they make 60+45=105 minutes.','RATE-01',[75,90,100,135],check=60+3*60//4))
 p.append(item('The diagram shows a square with one diagonal. How many triangles are drawn, counting only triangles whose sides are shown?',2,'The diagonal splits the square into two triangles. No third triangle can be formed because the other diagonal is not drawn.','SPATIAL-01',[1,3,4,5],figure=svg('<rect x="110" y="30" width="180" height="180" fill="#eff5f7"/><path d="M110,30L290,210"/>')))
 p.append(item('A packet has 35 buttons. One fifth are blue. How many are blue?',7,'One fifth means divide the whole count into five equal groups. Thus 35÷5=7 blue buttons.','FRAC-01',[5,6,8,10],check=35//5))
 p.append(item('A farmer plants 9 rows of trees, with 7 trees in each row. How many trees are planted?',63,'There are nine equal groups of seven trees. Their total is 9×7=63.','COUNT-01',[16,56,64,72],check=9*7))
 p.append(item('A thermometer rises from 6°C to 19°C. By how many degrees does the temperature rise?',13,'Temperature rise is final temperature minus initial temperature: 19−6=13°C.','RATE-01',[11,12,14,25],check=19-6))
 p.append(item('A robot faces north. It turns right, then right again, then left. Which way does it face?','East','Trace the turns: north→east→south→east. Two right turns and one left turn have the net effect of one right turn.','SPATIAL-02',['North','South','West','North-west']))
 p.append(item('A number is multiplied by 5 and then increased by 7 to give 92. What is the number?',17,'Reverse the operations: 92−7=85, then 85÷5=17. Check 17×5+7=92.','ALG-04',[15,16,18,19],check=(92-7)//5))
 p.append(item('A rectangular paddock is 20 m long and 15 m wide. A square pond with side 5 m occupies one corner. What area of paddock remains outside the pond?', '275 m²','The paddock area is 20×15=300 m². The pond area is 5×5=25 m². Subtract to obtain 275 m².','GEO-02',['250 m²','280 m²','295 m²','325 m²']))
 p.append(item('Four teams each play every other team once. How many matches are played?',6,'Each of four teams has three opponents, giving 12 team appearances. Every match accounts for two appearances, so 12÷2=6 matches.','COUNT-05',[4,8,10,12],check=math.comb(4,2)))
 p.append(item('The ratio of flour to sugar in a mixture is 5:2 by mass. The mixture has mass 420 g. How much sugar is in it?', '120 g','The mixture contains seven ratio parts. Each part is 420÷7=60 g. Sugar accounts for two parts, or 120 g.','FRAC-02',['84 g','140 g','168 g','300 g']))
 p.append(item('A regular pattern uses rows containing 1, 3, 5, 7, … dots. How many dots are in the first seven rows altogether?',49,'The first seven odd numbers are 1,3,5,7,9,11,13. Pair the outer terms: three pairs of 14 plus the middle 7 gives 49. These rows can also build a 7×7 square.','SEQ-03',[42,48,56,64],check=sum(range(1,14,2))))
 p.append(item('A fair six-sided die is rolled. What is the probability that the result is a factor of 6?','2/3','The factors of 6 shown on the die are 1,2,3,6: four favourable outcomes out of six. The probability is 4/6=2/3.','DATA-01',['1/3','1/2','5/6','1/6'],check=str(F(4,6))))
 p.append(item('There are 28 students. Each chooses exactly one of art or music. Five more choose art than would choose art if the groups were equal. How many choose music?',9,'Equal groups would contain 14 each. Art has five more, so it has 19. Music has the remaining 28−19=9 students.','ALG-02',[5,10,14,19],check=28-(28//2+5)))
 p.append(item('Two sides of a triangle are 5 cm and 9 cm. Its third side is a whole number of centimetres. How many values can that third side have?',9,'The triangle inequality requires the third side to exceed 9−5=4 and be less than 9+5=14. The whole numbers 5 through 13 give nine values. Equalities would make a flat shape.','GEO-03',[8,10,11,12],check=len(range(5,14))))
 p.append(item('The three-digit number 4□6 is divisible by 9. What digit replaces the square?',8,'A number is divisible by 9 exactly when its digit sum is. Here the sum is 10+□, between 10 and 19. It must be 18, so □=8.','DIG-04',[0,2,4,9],check=next(d for d in range(10) if (406+10*d)%9==0)))
 p.append(item('A class raises $360. It spends 25% on materials and then half of the remaining money on transport. How much is left?','$135','Materials cost $90, leaving $270. Half of that is spent on transport, so the other half, $135, remains. The second fraction applies to the remaining amount.','FRAC-03',['$90','$120','$180','$225']))
 p.append(item('A box has 30 balls numbered 1 to 30. How many balls have numbers that are multiples of 4 or contain the digit 4?',8,'Multiples of 4 are 4,8,12,16,20,24,28: seven numbers. Numbers containing 4 are 4,14,24. Only 14 is new, so the total is eight.','COUNT-04',[7,9,10,11],check=sum(n%4==0 or '4' in str(n) for n in range(1,31))))
 p.append(item('A rectangular prism has width 5 cm, depth 4 cm and height 3 cm. What is the sum of the lengths of all its edges?', '48 cm','A rectangular prism has four edges of each dimension. The total is 4×5+4×4+4×3=4×12=48 cm.','SOLID-03',['24 cm','36 cm','60 cm','94 cm'],figure=cuboid(5,4,3)))
 p.append(item('A boat travels 18 km downstream in 2 hours and 18 km upstream in 3 hours. Its speed in still water and the current speed are constant. What is the current speed?', '1.5 km/h','Downstream speed is 9 km/h and upstream speed is 6 km/h. Their difference, 3 km/h, equals twice the current speed, because the current is added in one direction and subtracted in the other. Hence the current is 1.5 km/h.','RATE-04',['1 km/h','2 km/h','3 km/h','7.5 km/h']))
 p.append(item('How many two-digit positive numbers have a tens digit greater than their units digit?',45,'For tens digits 1 through 9, the number of allowed units digits is respectively 1 through 9, including zero. Add 1+2+…+9=45.','DIG-02',[36,40,44,54],check=sum(n//10>n%10 for n in range(10,100))))
 p.append(item('A square and a rectangle have the same area. The rectangle is 18 cm by 8 cm. How much larger is the rectangle’s perimeter than the square’s?', '4 cm','The common area is 18×8=144 cm², so the square has side 12 and perimeter 48 cm. The rectangle has perimeter 2(18+8)=52 cm. The difference is 4 cm.','GEO-05',['2 cm','6 cm','8 cm','12 cm']))
 p.append(item('A proper fraction is in simplest form. Its positive numerator and denominator sum to 24. How many such fractions are there?',4,'Write the fraction as a/(24−a), with 1≤a≤11. Its two numbers are coprime exactly when a and 24 are coprime. In that range the choices are a=1,5,7,11. The fractions are 1/23,5/19,7/17,11/13, so there are four.','FRAC-01',check=sum(math.gcd(a,24-a)==1 for a in range(1,12))))
 p.append(item('A 5-by-5 board has its central square removed. How many axis-aligned rectangles of squares can be chosen without including the removed square?',144,'The full board has (6 choose 2)²=225 rectangles. A rectangle containing the centre has 3 choices each for its left, right, top and bottom boundaries, giving 3⁴=81. Subtract to obtain 225−81=144.','COUNT-04',check=math.comb(6,2)**2-3**4,figure=grid(5,5,[(2,2)])))
 p.append(item('A positive integer N is less than 1000. N/2 is a perfect square and N/3 is a perfect cube. What is N?',648,'Factor exponents give the shortcut. For N/2 to be square, the exponent of 2 in N is odd and all other exponents are even. For N/3 to be cube, the exponent of 3 is 1 more than a multiple of 3 and all other exponents are multiples of 3. The smallest compatible exponents are 3 for 2 and 4 for 3, so N is divisible by 2³×3⁴=648. Increasing any compatible exponent adds 6 and exceeds 1000. Check 648/2=18² and 648/3=6³.','DIV-01',check=next(n for n in range(1,1000) if n%6==0 and math.isqrt(n//2)**2==n//2 and any(k**3==n//3 for k in range(1,10)))))
 seating=sum(all(abs(z.index(2*i)-z.index(2*i+1)) not in [1,5] for i in range(3)) for zz in permutations(range(1,6)) for z in [(0,)+zz])
 p.append(item('Three pairs of friends sit around a circular table. No one may sit beside their partner. Arrangements that differ only by rotation are the same, but reflections are different. How many arrangements are possible?',32,'There are 5!=120 unrestricted circular arrangements. If a specified pair sits together, treat it as one block: 2×4!=48 arrangements. For two specified pairs, there are 2²×3!=24; for all three, 2³×2!=16. Inclusion–exclusion gives 120−3×48+3×24−16=32. The block method includes partners across the chosen starting position.','COUNT-04',check=seating))
 ways=[1,1,1,1]
 for n in range(2,6):ways=[sum(ways[j] for j in range(4) if not(i==j and i in [0,3])) for i in range(4)]
 p.append(item('Each square of a 2-row, 5-column board is coloured black or white. No 2-by-2 block may be all one colour. How many colourings are possible? Rotations and reflections count as different.',634,'Track the last column as BB, BW, WB or WW. With one column each count is 1. A new BB can follow every type except BB; a new WW can follow every type except WW; either mixed type can follow anything. The four counts after 2,3,4,5 columns are (3,4,4,3), (11,14,14,11), (39,50,50,39), (139,178,178,139). Add the final counts: 634. Every forbidden monochrome block occurs between adjacent columns, so these are all the restrictions.','COUNT-03',check=sum(ways),figure=grid(5,2)))
 one=paper('amc',7,p)
 p=[]
 p.append(item('What is 600 ÷ 25?',24,'Four groups of 25 make 100. Six hundreds therefore contain 6×4=24 groups of 25.','DIG-01',[12,15,20,25],check=600//25))
 p.append(item('Which number is ten times 3.07?','30.7','Multiplying by ten shifts each digit one place in value. Thus 3.07 becomes 30.7, not 3.70.','DIG-01',['3.70','30.07','307','0.307']))
 p.append(item('A box contains 5 layers of 12 cans. How many cans are in three such boxes?',180,'One box contains 5×12=60 cans. Three boxes contain 3×60=180 cans.','COUNT-01',[60,90,120,150],check=3*5*12))
 p.append(item('A triangle has angles 90° and 35°. What is its third angle?', '55°','The angles total 180°. Subtract the known angles: 180−90−35=55°.','GEO-03',['35°','45°','65°','125°']))
 p.append(item('A sandwich costs $4.80 and a drink costs $2.20. How many dollars do they cost together?',7,'Add cents carefully: 480+220=700 cents. This is exactly seven dollars.','DIG-01',[6,6.8,7.2,8],check=(480+220)//100))
 p.append(item('Which fraction is equal to 0.25?','1/4','The decimal 0.25 means 25/100. Divide the numerator and denominator by 25 to simplify it to 1/4.','FRAC-01',['1/2','1/5','2/5','3/4']))
 p.append(item('How many faces does a cube have?',6,'A cube has a top and bottom, a front and back, and a left and right face: three pairs, or six faces.','SOLID-03',[4,5,8,12]))
 p.append(item('The smallest of four numbers is 17 and their range is 28. What is the greatest number?',45,'Range is greatest minus least. Therefore greatest=17+28=45.','DATA-02',[11,28,35,46],check=17+28))
 p.append(item('A path has signposts numbered 1 to 16. How many signposts have even numbers?',8,'The even labels are 2,4,6,8,10,12,14,16. There are eight, or half of the sixteen labels.','DIV-04',[6,7,9,10],check=16//2))
 p.append(item('A 24 cm ribbon is cut into three pieces of equal length. What is the length of two of those pieces together?', '16 cm','Each piece has length 24÷3=8 cm. Two pieces together measure 2×8=16 cm.','FRAC-01',['8 cm','12 cm','18 cm','21 cm']))
 p.append(item('A number pattern starts at 90 and repeatedly subtracts 7. What is the sixth term?',55,'The first term is already 90. Five subtractions reach term six, giving 90−5×7=55.','SEQ-01',[48,53,56,62],check=90-5*7))
 p.append(item('An octagon has eight vertices. How many line segments join pairs of vertices, including sides and diagonals?',28,'Every segment corresponds to a pair of vertices. Count 8×7 ordered choices, then divide by 2 because reversing the endpoints gives the same segment: 28.','COUNT-05',[20,24,32,56],check=math.comb(8,2)))
 p.append(item('A bicycle wheel travels 2 m in one full turn. How many full turns does it make in travelling 1.5 km?',750,'Convert 1.5 km to 1500 m. Each turn covers 2 m, so the number of turns is 1500÷2=750.','RATE-01',[75,300,500,3000],check=1500//2))
 p.append(item('A bag contains 9 red counters and 6 blue counters. How many blue counters must be added so that red counters make up exactly one third of the bag?',12,'Nine red counters must become one third of a total of 27. There are currently 15 counters, so add 27−15=12 blue counters.','FRAC-02',[3,6,9,18],check=9*3-15))
 p.append(item('A square of side 10 cm contains a smaller square of side 6 cm. What is the area outside the smaller square but inside the larger?', '64 cm²','Subtract the two areas: 10²−6²=100−36=64 cm². Subtracting the sides before squaring would not give the area difference.','GEO-02',['16 cm²','40 cm²','60 cm²','84 cm²']))
 p.append(item('A team’s mean score over five games is 18. Its total after four games was 67. What did it score in game five?',23,'The final total must be 5×18=90. The fifth game supplies the difference 90−67=23.','DATA-02',[18,20,21,25],check=5*18-67))
 p.append(item('Which is the least positive whole number divisible by 8, 12 and 15?',120,'The required prime factors are 2³ from 8, 3 from 12, and 5 from 15. Their product is 8×3×5=120. Any common multiple must contain all of these factors.','DIV-02',[60,90,180,240],check=math.lcm(8,12,15)))
 p.append(item('Five children sit in a row. Maya must sit at one end. How many seating orders are possible?',48,'Choose Maya’s end in 2 ways. The other four children can be ordered in 4×3×2×1=24 ways. Hence there are 2×24=48 orders.','COUNT-02',[24,36,60,120],check=2*math.factorial(4)))
 p.append(item('A rectangle is folded exactly in half so that its two short sides meet. It originally measures 18 cm by 10 cm. What is the perimeter of the folded rectangle?', '38 cm','Bringing the short sides together halves the 18 cm length. The folded dimensions are 9 cm by 10 cm, with perimeter 2(9+10)=38 cm.','SPATIAL-03',['28 cm','36 cm','46 cm','56 cm']))
 p.append(item('A number has exactly two digits. The product of its digits is 24 and the tens digit is smaller than the units digit. What is the sum of all possible such numbers?',84,'The distinct digit pairs with product 24 are (3,8) and (4,6), since (2,12) is not a digit pair. The numbers are 38 and 46. Their sum is 84.','DIG-02',[62,74,86,168],check=sum(n for n in range(10,100) if (n//10)*(n%10)==24 and n//10<n%10)))
 p.append(item('A box contains equal numbers of red and blue balls. After 12 red balls are removed, blue balls are three quarters of the remaining balls. How many balls were there originally?',36,'Let each original colour count be x. The new red count x−12 is one third of the blue count x, so 3(x−12)=x. Thus 2x=36 and x=18. There were 36 balls originally; afterwards 6 red and 18 blue remain.','ALG-03',[24,30,48,72],check=36))
 p.append(item('A two-digit number increases by 45 when its digits are reversed. Its digit product is 14. What is the original number?',27,'A reversal changes a two-digit number by 9 times the digit difference. Thus the units digit is 5 greater than the tens digit. The digits with product 14 are 2 and 7, giving 27. Check 72−27=45.','DIG-05',[14,41,72,95],check=next(n for n in range(10,100) if (n//10)*(n%10)==14 and int(str(n)[::-1])-n==45)))
 p.append(item('A tap fills a pool in 8 hours and another tap fills it in 12 hours. Both start together in an empty pool. How long do they take?', '4 hours 48 minutes','Together they fill 1/8+1/12=5/24 of the pool each hour. The time is 24/5 hours=4.8 hours. The decimal 0.8 hour is 48 minutes, so the time is 4 hours 48 minutes.','RATE-02',['4 hours 30 minutes','5 hours','6 hours','10 hours']))
 p.append(item('A cuboid is made from unit cubes, with width 6, depth 4 and height 3. It is painted on all outer faces. How many cubes have no paint?',8,'Unpainted cubes must lie away from every outer face. Remove one layer from each side of each dimension: (6−2)(4−2)(3−2)=4×2×1=8.','SOLID-02',[6,12,16,24],check=(6-2)*(4-2)*(3-2),figure=cuboid(6,4,3)))
 p.append(item('Three positive whole numbers have sum 20, and each is less than 10. How many ordered triples are possible?',36,'Without the upper limits there are 19 choose 2=171 positive triples, found by placing two separators among 19 gaps. If a specified entry is at least 10, subtract 9 from it to get positive triples summing to 11: 10 choose 2=45. Two entries cannot both be at least 10. Hence 171−3×45=36.','COUNT-04',[27,30,42,45],check=sum(a+b+c==20 for a,b,c in product(range(1,10),repeat=3))))
 p.append(item('A rectangle has integer side lengths and area 144 cm². Its longer side is less than twice its shorter side. How many different rectangles are possible, including a square?',2,'List factor pairs of 144 up to the square root: (1,144),(2,72),(3,48),(4,36),(6,24),(8,18),(9,16),(12,12). Only (9,16) and (12,12) satisfy longer < twice shorter. Thus there are two.','GEO-05',check=sum(144%a==0 and a<=144//a<2*a for a in range(1,145))))
 p.append(item('A staircase has ten steps. A climber moves up 1, 2 or 3 steps at a time, using a 3-step move exactly once. How many different move sequences reach the top?',130,'After the one 3-step move, the 1- and 2-step moves total 7. If the number of 2-step moves is 0,1,2,3, the numbers of 1-step moves are 7,5,3,1. Arrange the moves in these four cases: 8; 7!/(5!1!)=42; 6!/(3!2!)=60; 5!/(1!3!)=20. Their total is 130. The single 3-step move is distinct and can occur anywhere.','COUNT-02',check=sum(math.factorial((7-2*b)+b+1)//math.factorial(7-2*b)//math.factorial(b) for b in range(4))))
 p.append(item('A number has exactly 12 positive divisors. It is divisible by 18 but not by 4. What is the smallest such number?',90,'The exponent of 2 is exactly 1, while the exponent of 3 is at least 2. Divisors are counted by multiplying one more than each exponent. The smallest choice using another prime is 2¹×3²×5¹=90, giving 2×3×2=12 divisors. Using only 2 and 3 requires 2×(b+1)=12, so b=5 and the number is 486. Higher exponents or larger extra primes cannot improve on 90.','DIV-01',check=next(n for n in range(18,1000,18) if n%4!=0 and len(divisors(n))==12)))
 p.append(item('Nine identical counters are placed in three labelled boxes. Every box must contain at least one counter, and no box may contain more than five. How many distributions are possible?',19,'Positive distributions with no upper limit number 8 choose 2=28. If a specified box has at least six counters, remove five from it; the remaining positive counts sum to 4 and have 3 choose 2=3 possibilities. Two overfull boxes cannot occur. Subtract 3 boxes×3 possibilities: 28−9=19.','COUNT-04',check=sum(a+b+c==9 for a,b,c in product(range(1,6),repeat=3))))
 p.append(item('A four-digit number has four different digits. Multiplying it by 4 reverses its digits. What is the sum of its digits?',18,'Write 4×ABCD=DCBA. Since the product has four digits, A is 1 or 2. The units equation 4D ends in A rules out A=1, so A=2 and D is 3 or 8. The product is at least 8000, so D=8. The units carry is 3; the carry into the thousands must be 0 since 4×2 already gives 8. Let u be the carry from tens to hundreds. The middle columns give 4C+3=B+10u and 4B+u=C. Substituting gives 15B+3=6u. A carry u is at most 3, so B can only be 0 or 1; B=0 would make u noninteger. Thus B=1,u=3,C=7. Check 2178×4=8712. The digit sum is 18.','DIG-05',check=18))
 return [one,paper('amc',8,p)]
